data.query:
query ($whereI: InventoryWhereInput!, $whereWI: WorkcenterInputWhereInput, $whereW: WorkcenterWhereInput) {
  inventory(where: $whereI) {
    edges {
      node {
        id
        productStrategyProcessId
        productId
        workOrderProcessId
        inventoryTypeId
        lotId
        masterInventory {
          id
          allowUnload
        }
        quantity {
          value
          unitId
        }
        inventoryStatus {
          id
          name
          defective
          productionLoaded
          productionPrevent
          containment
          active
        }
        locationId
        number
        active
        barcode
        productionSetupMaterials(first: 1) {
          edges {
            node {
              id
              productionSetup {
                workcenterId
              }
            }
          }
        }
      }
    }
  }
  workcenterInput(where: $whereWI) {
    edges {
      node {
        id
        name
        order
        locationId
      }
    }
  }
  workcenter(where: $whereW) {
    edges {
      node {
        id
        shiftGroupId
        productionSetup {
          id
          modeId
          eventId
          outputs {
            edges {
              node {
                workOrder {
                  workOrderTypeId
                  workOrderProcesses(orderBy: {field: order, direction: asc}) {
                    edges {
                      node {
                        id
                      }
                    }
                  }
                }
                workOrderProcessId
                workOrderProcess {
                  code
                  order
                }
              }
            }
          }
        }
      }
    }
  }
}

