branches.transform:
(
  inventory.edges.node.inventoryTypeId = "WIP" and
  (workcenter.edges.node.productionSetup.outputs.edges.node.workOrder.workOrderTypeId!="Rework"
  or $.workcenter.edges.node.productionSetup.outputs.edges.node.workOrderProcessId != 
  $.workcenter.edges.node.productionSetup.outputs.edges.node.workOrder.workOrderProcesses.edges[0].node.id  )?(
    $inventoryWorkorderProcessId := inventory.edges.node.workOrderProcessId;

    $doWorkorderProcessMatchSetups := [workcenter.edges.node.productionSetup.outputs.edges.node.(

      $workorderProcessId := workOrderProcessId;
      $expectedWorkorderProcessIdForWip := $filter(
        [workOrder.workOrderProcesses.edges.node.id],
        function($v,$index, $arr ){ $arr[$index+1] = $workorderProcessId }
      );

      $inventoryWorkorderProcessId = $expectedWorkorderProcessIdForWip;
    )];

    true in $doWorkorderProcessMatchSetups = false
  )
  :
  false
)

