data.query:
query Query($where: ProductionSetupWhereInput, $assetNumber: String!) {
  setup: productionSetup(where: $where) {
    edges {
      node {
        id
        outputs {
          edges {
            node {
              id
              productStrategyProcess {
                productStrategyProcessAssets {
                  edges {
                    node {
                      assetDesignId
                      assetGroupDesignId
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  productionAsset(where: {_or: [{asset: {number: {_eq: $assetNumber}}}, {assetGroup: {number: {_eq: $assetNumber}}}]}) {
    edges {
      node {
        id
      }
    }
  }
  asset(where: {number: {_eq: $assetNumber}}) {
    edges {
      node {
        id
        number
        assetDesignId
      }
    }
  }
  assetGroup(where: {number: {_eq: $assetNumber}}) {
    edges {
      node {
        id
        number
        assetGroupDesignId
      }
    }
  }
}

